import { Activity, ArrowRight, BarChart3, CalendarDays, CheckCircle2, ChevronRight, CircleHelp, ClipboardCheck, Download, FileBarChart2, FileText, Flag, LayoutDashboard, Link2, MessageSquareText, Megaphone, Package, PanelLeft, Search, Settings2, ShoppingBag, Sparkles, Target, Users, Wallet, X } from "lucide-react";
import { CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
