type Action = { id:string; priority:string; title:string; area:string; evidence:string; owner:string; confidence:string; status:string; review:string; action:string; impact:string; hypothesis:string; control:string; duration:string; success:string; history:{at:string;event:string;note:string}[]; measurement?:{control:number;test:number;period:string;note:string} };
type Detail = {type:string;id?:string}|null;
const R=initialActions as Action[];
const nav=[
  {title:"PERFORMANCE",items:[{id:"overview",label:"Overview",icon:LayoutDashboard},{id:"d2c",label:"D2C",icon:BarChart3}]},
  {title:"SHOPIFY",items:[{id:"shopify",label:"KPI Dashboard",icon:ShoppingBag},{id:"trends",label:"Trends",icon:Activity},{id:"daily",label:"Daily Dashboard",icon:CalendarDays},{id:"products",label:"Product DRR",icon:Package},{id:"scenario",label:"Target Scenario",icon:Target},{id:"actions",label:"Action Plan",icon:ClipboardCheck}]},
  {title:"META ADS",items:[{id:"meta",label:"Campaigns & creatives",icon:Megaphone}]},
  {title:"GOOGLE ADS",items:[{id:"google",label:"Campaigns & creatives",icon:Search}]},
  {title:"CUSTOMERS",items:[{id:"crm",label:"Customers & CRM",icon:Users}]},
  {title:"REPORTS",items:[{id:"reports",label:"Reports",icon:FileText}]},
  {title:"OPERATIONS",items:[{id:"connections",label:"Connections",icon:Link2},{id:"users",label:"Users",icon:Users},{id:"tasks",label:"Tasks",icon:ClipboardCheck},{id:"review",label:"Review checklist",icon:CheckCircle2}]},
];
const titles=Object.fromEntries(nav.flatMap(g=>g.items.map(i=>[i.id,i.label])));
const amount=(n:number)=>"₹"+Math.round(n).toLocaleString("en-IN");
const compact=(n:number)=>n>=10000000?`₹${(n/10000000).toFixed(2)} Cr`:n>=100000?`₹${(n/100000).toFixed(2)} L`:amount(n);
const integer=(n:number)=>Math.round(n).toLocaleString("en-IN");
const percent=(n:number)=>`${(n*100).toFixed(2)}%`;
const multiple=(n:number|null)=>n===null?"—":`${n.toFixed(2)}x`;
const dateLabel=(n:number)=>`${29-n}–28 Sep 2026`;
const stamp=()=>new Date().toLocaleString("en-IN",{timeZone:"Asia/Kolkata",day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"});
const statusTone=(v:string)=>["Urgent","High"].includes(v)?"status-red":["Approved","Measured","Available"].includes(v)?"status-green":["Proposed","Medium","In test"].includes(v)?"status-amber":"status-blue";
function Status({value}:{value:string}){return <Badge className={`status ${statusTone(value)}`}>{value}</Badge>}
function SectionCard({title,subtitle,action,children}:{title:string;subtitle?:string;action?:React.ReactNode;children:React.ReactNode}){return <Card className="soft-card gap-0 py-0"><div className="card-head"><div><h2 className="section-title">{title}</h2>{subtitle&&<p className="meta-copy mt-1">{subtitle}</p>}</div>{action}</div><div className="card-body">{children}</div></Card>}
function DataTable({heads,rows}:{heads:string[];rows:React.ReactNode[][]}){return <div className="overflow-auto"><Table className="data-table"><TableHeader><TableRow>{heads.map(h=><TableHead key={h} className={/[₹%]|Spend|Revenue|ROAS|Orders|Clicks|CTR|CPO|CAC/.test(h)?"numeric":""}>{h}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map((cells,i)=><TableRow key={i}>{cells.map((c,j)=><TableCell key={j} className={/[₹%]|Spend|Revenue|ROAS|Orders|Clicks|CTR|CPO|CAC/.test(heads[j])?"numeric":""}>{c}</TableCell>)}</TableRow>)}</TableBody></Table></div>}
function EmptyNote({children}:{children:React.ReactNode}){return <div className="callout">{children}</div>}

export default function CommerceApp(){
  const [view,setView]=useState("overview"),[n,setN]=useState(7),[detail,setDetail]=useState<Detail>(null),[actions,setActions]=useState<Action[]>(()=>structuredClone(R)),[filter,setFilter]=useState("All"),[reportKind,setReportKind]=useState("daily"),[reportReady,setReportReady]=useState(false),[checklist,setChecklist]=useState<Record<string,boolean>>({}),[question,setQuestion]=useState(""),[agentAnswer,setAgentAnswer]=useState<React.ReactNode>(null),[scenario,setScenario]=useState(5),[selectedCampaign,setSelectedCampaign]=useState("M-P"),[testControl,setTestControl]=useState(""),[testVariant,setTestVariant]=useState(""),[testNote,setTestNote]=useState("");
  const p=period(n),prev=period(n,true),a=metrics(p),b=metrics(prev);
  const daily=useMemo(()=>within(days,p).map(d=>{const m=metrics({start:d.date,end:d.date});return {label:d.date.slice(-2),date:d.date,...m}}),[n]);
  useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem("bb-commerce-shadcn-v1")||"null");if(saved){if(Array.isArray(saved.actions))setActions(saved.actions);if(saved.checklist)setChecklist(saved.checklist)}}catch{}},[]);
  useEffect(()=>{try{localStorage.setItem("bb-commerce-shadcn-v1",JSON.stringify({actions,checklist}))}catch{}},[actions,checklist]);
  useEffect(()=>{const v=location.hash.slice(1);if(titles[v])setView(v)},[]);
  useEffect(()=>{
    type BrowserTool={name:string;title:string;description:string;inputSchema:object;annotations:{readOnlyHint:boolean;untrustedContentHint:boolean};execute:(input:unknown)=>unknown};
    const context=(document as Document & {modelContext?:{registerTool:(tool:BrowserTool,options:{signal:AbortSignal})=>Promise<void>|void}}).modelContext;
    if(!context?.registerTool)return;
    const controller=new AbortController();
    const register=(tool:BrowserTool)=>{try{void Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}};
    register({name:"read_commerce_performance",title:"Read Commerce performance",description:"Read the visible synthetic Commerce OS totals for the selected period.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({period:dateLabel(n),demo_data:true,shopify_revenue:a.revenue,paid_media_spend:a.spend,website_roas:a.roas,orders:a.orders,new_customer_cac:a.cac})});
    register({name:"approve_commerce_action",title:"Approve a Commerce test",description:"Approve an existing proposed demo action for a controlled test and update the visible action list.",inputSchema:{type:"object",properties:{action_id:{type:"string",enum:["A01","A02","A03"]}},required:["action_id"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:(input)=>{const id=(input as {action_id?:string})?.action_id;const item=actions.find(v=>v.id===id);if(!item||item.status!=="Proposed")throw Error("Action must exist and be Proposed");setActions(list=>list.map(v=>v.id===id?{...v,status:"Approved",history:[...v.history,{at:stamp(),event:"Approved for test",note:"Approved through the prototype tool"}]}:v));return {action_id:id,status:"Approved",demo_data:true}}});
    return()=>controller.abort();
  },[n,actions]);
  const navigate=(v:string)=>{if(!titles[v])return;setView(v);location.hash=v;setDetail(null);window.scrollTo(0,0)};
  const update=(id:string,patch:Partial<Action>,event:string,note="")=>setActions(list=>list.map(item=>item.id===id?{...item,...patch,history:[...item.history,{at:stamp(),event,note}]}:item));
  const actionBy=(id:string)=>actions.find(item=>item.id===id);
  const metricCalc=(id:string)=>{
    switch(id){case"roas":return {title:"Website ROAS",formula:`${amount(a.revenue)} ÷ ${amount(a.performanceSpend)} = ${multiple(a.roas)}`,why:"Shopify net merchandise revenue divided by performance media spend for the same period. Awareness delivery is reported separately and is not treated as sales ROAS, as stated in the SOW.",source:"Shopify orders + Meta/Google performance campaigns; awareness excluded"};
      case"revenue":return {title:"Online revenue",formula:`${amount(a.newRevenue)} new + ${amount(a.returnRevenue)} returning = ${amount(a.revenue)}`,why:"Shopify merchandise revenue after discounts and refunds; shipping and tax are excluded.",source:"Shopify order ledger"};
      case"spend":return {title:"Total paid media spend",formula:`${campaigns.map(c=>amount(campaignMetrics(c.id,p).spend)).join(" + ")} = ${amount(a.spend)}`,why:"Total Meta and Google media cost, including awareness. Awareness is excluded from sales ROAS and shown separately in the investment ledger.",source:"Meta Ads + Google Ads daily campaign rows"};
      case"orders":return {title:"Shopify orders",formula:`${integer(a.orders)} Shopify order IDs`,why:"Count includes fully refunded orders; refunds reduce revenue. GA4 tracked purchases are a separate measure.",source:"Shopify order ledger"};
      case"cac":return {title:"Blended new-customer CAC",formula:`${amount(a.acquisitionSpend)} ÷ ${integer(a.newCustomers)} = ${amount(a.cac)}`,why:"Acquisition-tagged media spend divided by unique first-time Shopify purchasers. This is a blended cost measure, not campaign-level causal attribution.",source:"Meta + Google acquisition campaign spend; Shopify first-time customer IDs"};
      case"cpo":return {title:"Cost per order",formula:`${amount(a.performanceSpend)} ÷ ${integer(a.orders)} = ${amount(a.cpo)}`,why:"Performance media spend divided by actual Shopify orders for the same period. Awareness spend is shown in total media spend and investment reporting.",source:"Meta + Google performance campaigns + Shopify"};
      case"aov":return {title:"Average order value",formula:`${amount(a.revenue)} ÷ ${integer(a.orders)} = ${amount(a.aov)}`,why:"Net Shopify merchandise revenue divided by orders.",source:"Shopify orders"};
      default:return {title:"Website conversion",formula:`${integer(a.purchases)} ÷ ${integer(a.sessions)} = ${percent(a.conversion)}`,why:"GA4 purchase events divided by GA4 sessions. Shopify order count is shown separately.",source:"GA4 sessions and purchase events"};}
  };
  const delta=(id:keyof typeof a,good=true)=>{const d=(a[id]/b[id]-1)*100;return <span className={(d>=0)===good?"delta-good":"delta-bad"}>{d>=0?"+":""}{d.toFixed(1)}% vs prior {n} days</span>};
  const kpi=(label:string,id:keyof typeof a,fmt:(n:number)=>string,good=true,featured=false)=><button key={id} className="kpi-click" onClick={()=>setDetail({type:"metric",id})}><Card className={`kpi-card ${featured?"featured":""}`}><div className="muted-copy">{label}</div><div className="kpi-value">{fmt(a[id] as number)}</div><div className="meta-copy">{delta(id,good)}</div>{featured&&<div className="meta-copy mt-2">Shopify revenue ÷ performance media spend · awareness excluded</div>}</Card></button>;
  const funnel=<><div className="funnel-grid">{[["Sessions","sessions"],["Product views","views"],["Add to cart","cart"],["Checkout","checkout"],["Purchases","purchases"]].map(([label,key])=><button className="funnel-item" key={key} onClick={()=>setDetail({type:"evidence",id:"checkout"})}><span>{label}</span><strong>{integer(a[key as keyof typeof a] as number)}</strong><Progress value={Math.max(3,(a[key as keyof typeof a] as number)/a.sessions*100)}/><span className="mt-2">{percent((a[key as keyof typeof a] as number)/a.sessions)} of sessions</span></button>)}</div><p className="meta-copy"><strong>GA4 source:</strong> sessions, product views, add-to-cart, checkout and purchase events. <strong>Shopify source of truth:</strong> orders, net revenue and customers ({integer(a.orders)} orders in this period). GA4 purchases/revenue stay visible as a measurement comparison and are not added to Shopify actuals.</p></>;
  const chart=<><div style={{width:"100%",height:245}}><ResponsiveContainer><LineChart data={daily} margin={{top:8,right:12,bottom:0,left:-10}}><CartesianGrid vertical={false} stroke="#e9eef5"/><XAxis dataKey="label" tickLine={false} axisLine={false} fontSize={12}/><YAxis tickFormatter={(v:number)=>`${(v/100000).toFixed(1)}L`} tickLine={false} axisLine={false} fontSize={12}/><Tooltip formatter={(value)=>amount(Number(value))} labelFormatter={(v)=>`${v} Sep 2026`}/><Line dataKey="revenue" stroke="#2563eb" strokeWidth={3} dot={false} name="Shopify revenue"/><Line dataKey="spend" stroke="#9aaac5" strokeWidth={2} strokeDasharray="5 4" dot={false} name="Media spend"/></LineChart></ResponsiveContainer></div><div className="mini-legend"><span><i/>Shopify net revenue</span><span><i style={{background:"#9aaac5"}}/>Paid media spend</span></div></>;
  const actionsTable=(limit=999)=>{const list=actions.filter(item=>filter==="All"||item.status===filter).slice(0,limit);return <Card className="table-card"><div className="table-heading"><div><h2 className="section-title"><Sparkles className="size-5 text-primary"/> Recommended actions</h2><p className="meta-copy mt-1">Finding → evidence → action → owner → measured result</p></div><Select value={filter} onValueChange={setFilter}><SelectTrigger className="w-[145px] bg-white" aria-label="Action status"><SelectValue/></SelectTrigger><SelectContent>{["All","Proposed","Approved","In test","Measured"].map(v=><SelectItem key={v} value={v}>{v} statuses</SelectItem>)}</SelectContent></Select></div><DataTable heads={["Priority","Action and evidence","Expected impact","Confidence","Owner","Status",""]} rows={list.map(item=>[<Status key="p" value={item.priority}/>,<div key="t"><strong>{item.title}</strong><div className="cell-sub">{item.area} · {item.action}</div></div>,<span key="i" className="text-xs text-muted-foreground">{item.impact}</span>,<Status key="c" value={item.confidence}/>,item.owner,<Status key="s" value={item.status}/>,<Button key="b" variant="outline" size="sm" onClick={()=>setDetail({type:"action",id:item.id})}>Review</Button>])}/></Card>};
  const overview=<><div className="kpi-grid">{kpi("Website ROAS","roas",multiple,true,true)}{kpi("Online revenue","revenue",compact)}{kpi("Paid media spend","spend",compact,false)}{kpi("Shopify orders","orders",integer)}</div><section className="analysis-panel"><div className="analysis-head"><h2 className="section-title"><Sparkles className="size-5 text-primary"/> What needs attention</h2><Button size="sm" variant="outline" onClick={()=>setDetail({type:"agent"})}>Ask the agent</Button></div><div className="analysis-grid"><div className="analysis-item"><div className="eyebrow">Urgent · Checkout</div><p>Completion from checkout to GA4 purchase is <strong>{percent(a.completion)}</strong> versus {percent(b.completion)} previously. Payment and checkout logs are needed to establish why.</p><Button size="sm" variant="link" className="p-0" onClick={()=>setDetail({type:"evidence",id:"checkout"})}>View evidence and action <ChevronRight/></Button></div><div className="analysis-item"><div className="eyebrow">Watch · Prospecting</div><p>Meta prospecting CTR is <strong>{percent(campaignMetrics("M-P",p).ctr)}</strong>. Test a refreshed message at equal budgets before making a broader change.</p><Button size="sm" variant="link" className="p-0" onClick={()=>setDetail({type:"campaign",id:"M-P"})}>Inspect campaign <ChevronRight/></Button></div><div className="analysis-item"><div className="eyebrow">Working · Brand Search</div><p>Brand Search shows <strong>{multiple(campaignMetrics("G-S",p).roas)}</strong> platform ROAS. Its attributed revenue can overlap other campaigns.</p><Button size="sm" variant="link" className="p-0" onClick={()=>setDetail({type:"campaign",id:"G-S"})}>Inspect campaign <ChevronRight/></Button></div></div></section><div className="chart-grid"><SectionCard title="Revenue movement" subtitle="Actual Shopify revenue alongside media investment" action={<Button size="sm" variant="ghost" onClick={()=>navigate("trends")}>Daily view <ArrowRight/></Button>}>{chart}</SectionCard><SectionCard title="Website funnel" subtitle="GA4 journey · Shopify actuals remain separate" action={<Button size="sm" variant="ghost" onClick={()=>navigate("shopify")}>Shopify view <ArrowRight/></Button>}>{funnel}</SectionCard></div>{actionsTable(5)}<EmptyNote>Blackberrys’ business aspiration is website ROAS moving from 2.7 toward 5.0 alongside online revenue growth. This prototype demonstrates visibility and decisions; the figures and impact estimates are synthetic.</EmptyNote></>;
  const d2c=<><div className="kpi-grid">{kpi("Website ROAS","roas",multiple,true,true)}{kpi("Online revenue","revenue",compact)}{kpi("Cost per order","cpo",amount,false)}{kpi("New-customer CAC","cac",amount,false)}</div><div className="grid-two"><SectionCard title="What changed?" subtitle="Current period compared with the previous equal period"><div className="space-y-4 text-sm"><p>Shopify revenue {delta("revenue")} and paid spend {delta("spend",false)}. This arithmetic moves blended website ROAS from {multiple(b.roas)} to {multiple(a.roas)}.</p><p>Orders {delta("orders")}; average order value {delta("aov")}. These are observed components, not proof of a causal driver.</p><p>Checkout completion moved from {percent(b.completion)} to {percent(a.completion)}. Review the funnel and payment evidence before deciding on a fix.</p><Button variant="outline" onClick={()=>setDetail({type:"evidence",id:"checkout"})}>Inspect funnel evidence</Button></div></SectionCard><SectionCard title="Channel spend" subtitle="Platform-reported outcomes are shown separately"><DataTable heads={["Source","Spend","Attributed revenue","Platform ROAS"]} rows={["Meta","Google"].map(platform=>{const rows=campaigns.filter(c=>c.platform===platform&&c.ratio!==null).map(c=>campaignMetrics(c.id,p));return [platform,amount(sum(campaigns.filter(c=>c.platform===platform).map(c=>campaignMetrics(c.id,p)),"spend")),amount(sum(rows,"revenue")),multiple(sum(rows,"revenue")/sum(rows,"spend"))]})}/><p className="meta-copy mt-3">Attribution overlap and awareness treatment must be agreed before cross-platform comparison.</p></SectionCard></div></>;
  const shopify=<><div className="kpi-grid">{kpi("Shopify revenue","revenue",compact,true,true)}{kpi("Orders","orders",integer)}{kpi("Average order value","aov",amount)}{kpi("GA4 conversion","conversion",percent)}</div><SectionCard title="Website funnel" subtitle="GA4 event counts, selected reporting period">{funnel}<Button variant="outline" className="mt-4" onClick={()=>setDetail({type:"evidence",id:"checkout"})}>Explain checkout drop</Button></SectionCard><div className="grid-two mt-5"><SectionCard title="New and returning revenue" subtitle="From actual Shopify order flags"><DataTable heads={["Customer type","Orders","Revenue"]} rows={[["First-time",a.orders-a.returnOrders,amount(a.newRevenue)],["Returning",a.returnOrders,amount(a.returnRevenue)]]}/><Button variant="link" className="px-0 mt-3" onClick={()=>navigate("crm")}>Open customer economics <ArrowRight/></Button></SectionCard><SectionCard title="Measurement comparison" subtitle="Two source measures, one period"><div className="facts"><div className="fact">Shopify orders<strong>{integer(a.orders)}</strong></div><div className="fact">GA4 purchases<strong>{integer(a.purchases)}</strong></div><div className="fact">Shopify net revenue<strong>{amount(a.revenue)}</strong></div><div className="fact">GA4 purchase revenue<strong>{amount(a.gaRevenue)}</strong></div></div><Button variant="link" className="px-0 mt-3" onClick={()=>setDetail({type:"evidence",id:"reconcile"})}>Investigate difference <ArrowRight/></Button></SectionCard></div></>;
  const trends=<><div className="grid-two"><SectionCard title="Revenue and spend" subtitle="Daily movement from the same source records">{chart}</SectionCard><SectionCard title="ROAS and conversion" subtitle="Daily values from Shopify, media and GA4"><div style={{width:"100%",height:245}}><ResponsiveContainer><LineChart data={daily}><CartesianGrid vertical={false} stroke="#e9eef5"/><XAxis dataKey="label" fontSize={12}/><YAxis fontSize={12}/><Tooltip formatter={v=>Number(v).toFixed(2)}/><Line dataKey="roas" stroke="#2563eb" strokeWidth={3} dot={false} name="Website ROAS"/><Line dataKey="conversion" stroke="#179984" strokeWidth={2} dot={false} name="GA4 conversion rate"/></LineChart></ResponsiveContainer></div><Button variant="link" className="px-0" onClick={()=>navigate("daily")}>Inspect daily rows <ArrowRight/></Button></SectionCard></div><EmptyNote>Each point uses the selected date’s Shopify orders and the corresponding ad-platform spend. Read the exact source values in Daily Dashboard.</EmptyNote></>;
  const dailyPage=<Card className="table-card"><div className="table-heading"><div><h2 className="section-title">Main Tracker · daily performance</h2><p className="meta-copy">Total media spend, performance spend, ROAS, revenue, orders, CPO, GA4 conversion and new-customer CAC</p></div><Button variant="outline" size="sm" onClick={()=>downloadDaily()}>Export CSV <Download/></Button></div><DataTable heads={["Date","Total media spend","Performance spend","Shopify revenue","Website ROAS","Shopify orders","CPO","GA4 conversion","New CAC"]} rows={daily.map(r=>[<Button key="d" variant="link" className="p-0" onClick={()=>setDetail({type:"day",id:r.date})}>{+r.date.slice(-2)} Sep</Button>,amount(r.spend),amount(r.performanceSpend),amount(r.revenue),multiple(r.roas),integer(r.orders),amount(r.cpo),percent(r.conversion),amount(r.cac)])}/></Card>;
  const productsPage=<><EmptyNote>Product DRR uses Shopify product IDs and order items in this synthetic sample. Inventory figures are illustrative snapshots.</EmptyNote><Card className="table-card mt-5"><div className="table-heading"><h2 className="section-title">Product performance</h2></div><DataTable heads={["Product","Category","Units","Revenue","Ending stock",""]} rows={products.map(product=>{const lines=within(orders,p).filter(o=>o.productId===product.id);return [<div key="n"><strong>{product.name}</strong><div className="cell-sub">{product.id}</div></div>,product.category,integer(lines.length),amount(sum(lines,"net")),integer(product.stock),<Button key="b" variant="outline" size="sm" onClick={()=>setDetail({type:"product",id:product.id})}>View orders</Button>]})}/></Card></>;
  const scenarioPage=<div className="grid-two"><SectionCard title="Target scenario" subtitle="Illustrative arithmetic, not a forecast"><p className="muted-copy">Explore how a higher order count would affect website ROAS at current performance media spend. Awareness spend is excluded from sales ROAS, and no campaign is changed.</p><div className="field"><Label>Additional Shopify orders: {scenario}</Label><Slider min={0} max={50} step={1} value={[scenario]} onValueChange={v=>setScenario(v[0])}/></div><div className="kpi-value text-primary">{multiple((a.revenue+scenario*a.aov)/a.performanceSpend)}</div><p className="meta-copy">({amount(a.revenue)} + {scenario} × {amount(a.aov)}) ÷ {amount(a.performanceSpend)} performance spend</p><Button variant="outline" onClick={()=>setDetail({type:"action",id:"A01"})}>Review checkout test</Button></SectionCard><SectionCard title="Decision guardrails" subtitle="Business target and measurement"><ul className="list-disc pl-5 space-y-3 text-sm leading-7"><li>Review online revenue alongside ROAS so reduced spending alone does not count as success.</li><li>New orders must be measured in Shopify; a hypothetical slider output is not a projected result.</li><li>Agree baseline, return basis and attribution rules with Blackberrys in Week 1.</li></ul></SectionCard></div>;
  const platformPage=(platform:"Meta"|"Google")=>{const list=campaigns.filter(c=>c.platform===platform);return <><div className="grid-two"><SectionCard title={`${platform} campaign performance`} subtitle="Platform-attributed revenue may overlap Shopify and other campaigns"><DataTable heads={["Campaign","Phase","Spend","Clicks","Platform ROAS",""]} rows={list.map(c=>{const m=campaignMetrics(c.id,p);return [<div key="c"><strong>{c.name}</strong><div className="cell-sub">{c.id} · {c.audience}</div></div>,c.phase,amount(m.spend),integer(m.clicks),m.roas===null?"Delivery only":multiple(m.roas),<Button key="b" variant="outline" size="sm" onClick={()=>setDetail({type:"campaign",id:c.id})}>Inspect</Button>]})}/></SectionCard><SectionCard title="Selected campaign" subtitle="Creative and daily evidence"><Select value={selectedCampaign} onValueChange={setSelectedCampaign}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{list.map(c=><SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>)}</SelectContent></Select>{list.some(c=>c.id===selectedCampaign)?<><div className="facts mt-5">{[["Spend",amount(campaignMetrics(selectedCampaign,p).spend)],["Clicks",integer(campaignMetrics(selectedCampaign,p).clicks)],["CTR",percent(campaignMetrics(selectedCampaign,p).ctr)],["Attributed revenue",campaignMetrics(selectedCampaign,p).revenue===null?"Not applicable":amount(campaignMetrics(selectedCampaign,p).revenue)]].map(([l,v])=><div className="fact" key={l}>{l}<strong>{v}</strong></div>)}</div><Button variant="link" className="px-0 mt-3" onClick={()=>setDetail({type:"campaign",id:selectedCampaign})}>View creative and daily rows <ArrowRight/></Button></>:<p className="muted-copy mt-5">Select a campaign from this platform.</p>}</SectionCard></div><Card className="table-card"><div className="table-heading"><h2 className="section-title">Creatives</h2></div><DataTable heads={["Creative","Campaign","Spend","Clicks","CTR",""]} rows={list.flatMap(c=>creativeMetrics(c.id,p)).map(cr=>[cr.name,cr.campaignId,amount(cr.spend),integer(cr.clicks),percent(cr.ctr),<Button key={cr.id} variant="outline" size="sm" onClick={()=>setDetail({type:"creative",id:cr.id})}>View evidence</Button>])}/></Card></>};
  const crmPage=<><div className="kpi-grid">{kpi("New customers","newCustomers",integer)}{kpi("New-customer CAC","cac",amount,false,true)}{kpi("First-time revenue","newRevenue",compact)}{kpi("Returning revenue","returnRevenue",compact)}</div><div className="grid-two"><SectionCard title="Acquisition economics" subtitle="Shopify first-time flags and acquisition-tagged media spend"><div className="facts"><div className="fact">First-time Shopify purchasers<strong>{integer(a.newCustomers)}</strong></div><div className="fact">Acquisition media spend<strong>{amount(a.acquisitionSpend)}</strong></div><div className="fact">Blended new-customer CAC<strong>{amount(a.cac)}</strong></div><div className="fact">Returning orders<strong>{integer(a.returnOrders)}</strong></div></div><Button variant="link" className="px-0 mt-3" onClick={()=>setDetail({type:"metric",id:"cac"})}>See CAC formula <ArrowRight/></Button></SectionCard><SectionCard title="CRM / Easy Rewards view" subtitle="Segment-led example; Shopify order IDs remain the revenue source"><DataTable heads={["Segment","Contacted","Linked orders","Net revenue"]} rows={[["Occasion shoppers",320,within(orders,p).filter(o=>!o.newCustomer&&+o.id.slice(-3)%4===0).length,amount(sum(within(orders,p).filter(o=>!o.newCustomer&&+o.id.slice(-3)%4===0),"net"))],["Everyday wardrobe",295,within(orders,p).filter(o=>!o.newCustomer&&+o.id.slice(-3)%5===0).length,amount(sum(within(orders,p).filter(o=>!o.newCustomer&&+o.id.slice(-3)%5===0),"net"))]]}/><p className="meta-copy mt-3">Illustrative linked-order subsets can overlap. Do not add CRM linked revenue to Shopify revenue.</p></SectionCard></div><div className="grid-two"><SectionCard title="Monthly acquisition cohorts" subtitle="Cohort membership from the available demo customer records"><DataTable heads={["First-purchase month","Customers","Observed repeat"]} rows={[["Jun 2026",customers.filter(c=>c.acquired==="2026-06").length,"Historical order count only"],["Jul 2026",customers.filter(c=>c.acquired==="2026-07").length,"Historical order count only"],["Sep 2026",customers.filter(c=>c.acquired==="2026-09").length,"No follow-up period yet"]]}/><p className="meta-copy mt-3">Repeat rate and first-to-second purchase timing need dated historical order exports from Easy Rewards / Shopify.</p></SectionCard><SectionCard title="Customer evidence" subtitle="Order-level traceability"><p className="muted-copy">Open a Shopify order to see its customer ID, first-time flag, product, discount, refund and net revenue.</p><Button variant="outline" onClick={()=>setDetail({type:"order",id:within(orders,p)[0]?.id})}>Inspect a sample order</Button></SectionCard></div></>;
  const reportsPage=<><div className="grid-two"><SectionCard title="Generate a report" subtitle="Blackberrys reporting language"><div className="field"><Label>Report format</Label><Select value={reportKind} onValueChange={v=>{setReportKind(v);setReportReady(false)}}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="daily">Daily performance · Main Tracker</SelectItem><SelectItem value="weekly">Weekly business review</SelectItem></SelectContent></Select></div><p className="muted-copy">Reporting period: {dateLabel(n)}. Values, exceptions and actions come from the same demo records used across the app.</p><div className="flex flex-wrap gap-2"><Button onClick={()=>setReportReady(true)}>Generate preview</Button><Button variant="outline" onClick={()=>reportKind==="daily"?downloadDaily():window.print()}>Export {reportKind==="daily"?"CSV":"PDF / print"}</Button></div></SectionCard><SectionCard title="Source and acceptance" subtitle="Week 1 decisions required"><p className="muted-copy">The report format follows Main Tracker and the weekly business review. Production sign-off requires reconciliation against the matching Blackberrys report and BE deck within a jointly agreed tolerance.</p><Button variant="outline" onClick={()=>navigate("connections")}>View data requirements</Button></SectionCard></div>{reportReady&&<div className="mt-5"><div className="report-banner"><h2>{reportKind==="daily"?"Daily Performance · Main Tracker":"Weekly Business Review"}</h2><p className="text-sm text-blue-100 mt-1">{dateLabel(n)} · Generated from synthetic Commerce OS records</p></div>{reportKind==="daily"?dailyPage:<><div className="kpi-grid">{kpi("Website ROAS","roas",multiple,true,true)}{kpi("Shopify revenue","revenue",compact)}{kpi("Orders","orders",integer)}{kpi("New CAC","cac",amount,false)}</div><SectionCard title="What changed and what to do"><p className="muted-copy">Revenue {delta("revenue")} while spend {delta("spend",false)}. Checkout completion is {percent(a.completion)} versus {percent(b.completion)}. Investigate checkout and test prospecting creative.</p></SectionCard><div className="mt-5">{actionsTable()}</div></>}</div>}</>;
  const sourceList=[{name:"Meta Ads",data:"Campaign IDs, dates, spend, impressions, clicks, creative IDs and attributed outcomes",refresh:"Approved API where accessible; recurring export otherwise",need:"Ad-account read access, campaign taxonomy"},{name:"Google Ads",data:"Campaign IDs, dates, cost, clicks, creative groups and conversions",refresh:"Approved API where accessible; recurring export otherwise",need:"Account read access, conversion definitions"},{name:"GA4",data:"Date, channel, sessions, product views, carts, checkouts and purchases",refresh:"Approved API or repeatable export",need:"Property access, event mapping"},{name:"Shopify",data:"Orders, net merchandise revenue, discounts, refunds, products, customer IDs",refresh:"Approved API or repeatable export",need:"Store read access, revenue definition"},{name:"Easy Rewards / CRM",data:"Customer ID, segment, campaign, sent/contacted, linked order IDs and costs",refresh:"API after third-party approval; scheduled export as fallback",need:"Vendor coordination, join-key mapping, history"}];
  const connectionsPage=<><EmptyNote>All source rows below are simulated. Production refresh targets and data access are to be agreed with Blackberrys; an upload is available when an API is delayed.</EmptyNote><Card className="table-card mt-5"><div className="table-heading"><h2 className="section-title">Source plan</h2></div><DataTable heads={["Source","Required data","Ingestion","Blackberrys input"]} rows={sourceList.map(s=>[<div key="s"><strong>{s.name}</strong><div className="cell-sub">Demo source available</div></div>,s.data,s.refresh,s.need])}/></Card><SectionCard title="Reconciliation rules" subtitle="Prevent misleading cross-source figures"><ul className="list-disc pl-5 space-y-2 text-sm leading-7"><li>Shopify orders and net merchandise revenue are the business actuals in this demo.</li><li>GA4 sessions and journey stages are measured separately; GA4 purchases need reconciliation.</li><li>Meta and Google attributed returns remain platform-labelled because campaigns can overlap.</li><li>CRM linked orders are subsets of Shopify orders, never additional business revenue.</li></ul></SectionCard></>;
  const usersPage=<SectionCard title="Owners and review roles" subtitle="Illustrative roles for action accountability"><DataTable heads={["Role","What they review","Example action"]} rows={[["Paid Media","Campaigns, audiences, creatives and test budgets","Creative refresh and budget decision"],["E-commerce","Shopify funnel, checkout and product performance","Checkout investigation"],["Analytics","Source mappings and reconciliation","GA4 purchase gap"],["Marketing Lead","Priority, impact and sign-off","Approve a controlled test"]]}/><p className="meta-copy mt-4">Named people and permissions will be confirmed during implementation.</p></SectionCard>;
  const reviewItems=["ROAS calculation opens its Shopify and media source basis","Campaign opens creative and daily platform records","GA4 funnel remains distinct from Shopify order actuals","New CAC has acquisition-spend and customer-ID basis","Recommendation has evidence, owner, impact and confidence","Action can move from proposal to approved test and recorded measurement","Main Tracker report exports and traces to the same records","Agent flags questions that the connected sample cannot answer"];
  const reviewPage=<><SectionCard title="Commerce OS sign-off walkthrough" subtitle="Check each step after trying the prototype">{reviewItems.map((item,i)=><label className="review-item" key={i}><input type="checkbox" checked={!!checklist[i]} onChange={e=>setChecklist(q=>({...q,[i]:e.target.checked}))} className="mt-1"/><span><strong>{item}</strong><span className="meta-copy">Review item {i+1}</span></span></label>)}<div className="flex gap-2 flex-wrap mt-5"><Button onClick={()=>downloadReview()}>Export review notes <Download/></Button><Button variant="outline" onClick={()=>navigate("overview")}>Return to overview</Button></div></SectionCard><p className="scope-note">This checklist is saved only in the reviewer’s browser. Export the notes to share feedback with the project team.</p></>;
  const page=()=>{switch(view){case"overview":return overview;case"d2c":return d2c;case"shopify":return shopify;case"trends":return trends;case"daily":return dailyPage;case"products":return productsPage;case"scenario":return scenarioPage;case"actions":return actionsTable();case"meta":return platformPage("Meta");case"google":return platformPage("Google");case"crm":return crmPage;case"reports":return reportsPage;case"connections":return connectionsPage;case"users":return usersPage;case"tasks":return actionsTable();case"review":return reviewPage;default:return overview}};
  function download(name:string,content:string,mime:string){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast.success(`${name} downloaded`)}
  function downloadDaily(){const quote=(v:string|number)=>`"${String(v).replaceAll('"','""')}"`;const lines=[["Demo data","Date","Total media spend INR","Performance media spend INR","Shopify net revenue INR","Website ROAS","Shopify orders","CPO INR","GA4 conversion rate","New CAC INR"],...daily.map(r=>["Synthetic",r.date,r.spend,r.performanceSpend,r.revenue,r.roas,r.orders,r.cpo,r.conversion,r.cac])];download("blackberrys-demo-main-tracker.csv",lines.map(row=>row.map(quote).join(",")).join("\n"),"text/csv;charset=utf-8")}
  function downloadReview(){download("blackberrys-commerce-review.json",JSON.stringify({module:"Commerce OS",data:"Synthetic",savedAt:stamp(),checks:reviewItems.map((label,i)=>({label,checked:!!checklist[i]})),actions},null,2),"application/json")}
  const detailTitle=()=>{if(!detail)return"";if(detail.type==="metric")return metricCalc(detail.id||"roas").title;if(detail.type==="campaign")return campaigns.find(c=>c.id===detail.id)?.name||"Campaign";if(detail.type==="creative")return"Creative evidence";if(detail.type==="action")return actionBy(detail.id||"")?.title||"Action";if(detail.type==="agent")return"Ask the Commerce agent";if(detail.type==="evidence")return detail.id==="checkout"?"Checkout evidence":"GA4 / Shopify reconciliation";return {day:"Daily source rows",product:"Product orders",order:"Shopify order"}[detail.type]||"Details"};
  const detailContent=()=>{
    if(!detail)return null;
    if(detail.type==="metric"){const m=metricCalc(detail.id||"roas");return <><Card className="detail-card"><div className="eyebrow">{dateLabel(n)} · Calculation</div><div className="formula">{m.formula}</div><p className="muted-copy">{m.why}</p><div className="source-note">Sources: {m.source} · Synthetic records · Definition pending Week 1 agreement</div></Card><div className="flex gap-2 flex-wrap"><Button variant="outline" onClick={()=>navigate("daily")}>Daily source rows</Button><Button variant="outline" onClick={()=>navigate("connections")}>Source coverage</Button></div></>}
    if(detail.type==="evidence"&&detail.id==="checkout"){const gap=Math.max(0,b.completion-a.completion),missed=a.checkout*gap,estimateLow=Math.round(missed*.25),estimateHigh=Math.round(missed*.5);return <><Card className="detail-card"><div className="facts"><div className="fact">Current checkout → purchase<strong>{percent(a.completion)}</strong></div><div className="fact">Previous comparable period<strong>{percent(b.completion)}</strong></div><div className="fact">Current GA4 checkouts<strong>{integer(a.checkout)}</strong></div><div className="fact">Current GA4 purchases<strong>{integer(a.purchases)}</strong></div></div><div className="formula">{integer(a.purchases)} ÷ {integer(a.checkout)} = {percent(a.completion)}</div><p className="muted-copy">Observed decline is an urgent signal. GA4 events alone cannot identify whether payment failures, UX, stock or tagging caused it.</p></Card><Card className="detail-card"><div className="eyebrow">Test idea · Not a forecast</div><p className="muted-copy">If a verified fix recovered 25–50% of the {integer(missed)} purchases implied by the earlier completion rate, the arithmetic range is {estimateLow}–{estimateHigh} additional purchases for this volume. The actual impact is unknown until a controlled test.</p><Button onClick={()=>setDetail({type:"action",id:"A01"})}>Review recommended test</Button></Card><p className="source-note">Source: GA4 daily sessions, checkout and purchase events · {dateLabel(n)}</p></>}
    if(detail.type==="evidence")return <><Card className="detail-card"><div className="facts"><div className="fact">Shopify orders<strong>{integer(a.orders)}</strong></div><div className="fact">GA4 purchase events<strong>{integer(a.purchases)}</strong></div><div className="fact">Shopify net revenue<strong>{amount(a.revenue)}</strong></div><div className="fact">GA4 purchase revenue<strong>{amount(a.gaRevenue)}</strong></div></div><p className="muted-copy">Different systems and definitions can produce differences. Match order IDs, refunds, event timing and revenue exclusions before attributing a cause.</p><Button onClick={()=>setDetail({type:"action",id:"A03"})}>Review reconciliation action</Button></Card></>;
    if(detail.type==="campaign"){const c=campaigns.find(v=>v.id===detail.id);if(!c)return null;const m=campaignMetrics(c.id,p);return <><Card className="detail-card"><div className="eyebrow">{c.platform} · {c.phase} · {c.id}</div><p className="muted-copy">Audience: {c.audience}</p><div className="facts"><div className="fact">Spend<strong>{amount(m.spend)}</strong></div><div className="fact">Clicks<strong>{integer(m.clicks)}</strong></div><div className="fact">CTR<strong>{percent(m.ctr)}</strong></div><div className="fact">Platform ROAS<strong>{m.roas===null?"Not reported":multiple(m.roas)}</strong></div></div><p className="source-note">Attributed revenue: {m.revenue===null?"Not applicable for awareness":amount(m.revenue)}. This is platform reporting, not incremental Shopify revenue.</p></Card><SectionCard title="Creative split" subtitle="Spend and clicks reconcile to campaign totals"><DataTable heads={["Creative","Spend","Clicks","CTR"]} rows={creativeMetrics(c.id,p).map(cr=>[<Button key={cr.id} variant="link" className="p-0" onClick={()=>setDetail({type:"creative",id:cr.id})}>{cr.name}</Button>,amount(cr.spend),integer(cr.clicks),percent(cr.ctr)])}/></SectionCard><Card className="detail-card mt-4"><div className="eyebrow">Daily platform rows</div><DataTable heads={["Date","Spend","Clicks","Attributed revenue"]} rows={m.rows.map(r=>[r.date,amount(r.spend),integer(r.clicks),r.attributedRevenue===null?"Delivery only":amount(r.attributedRevenue)])}/></Card>{c.id==="M-P"&&<Button onClick={()=>setDetail({type:"action",id:"A02"})}>Review creative test</Button>}</>}
    if(detail.type==="creative"){const cr=campaigns.flatMap(c=>creativeMetrics(c.id,p)).find(v=>v.id===detail.id);if(!cr)return null;return <><Card className="detail-card"><div className="eyebrow">Creative ID: {cr.id}</div><h3 className="font-semibold">{cr.name}</h3><div className="facts"><div className="fact">Spend<strong>{amount(cr.spend)}</strong></div><div className="fact">Clicks<strong>{integer(cr.clicks)}</strong></div><div className="fact">Impressions<strong>{integer(cr.impressions)}</strong></div><div className="fact">CTR<strong>{percent(cr.ctr)}</strong></div></div><p className="source-note">Illustrative creative split of the parent platform campaign; source record group: {cr.campaignId}.</p></Card><Button variant="outline" onClick={()=>setDetail({type:"campaign",id:cr.campaignId})}>Open parent campaign</Button>{cr.campaignId==="M-P"&&<Button className="ml-2" onClick={()=>setDetail({type:"action",id:"A02"})}>Review test</Button>}</>}
    if(detail.type==="day"){const date=detail.id||"",m=metrics({start:date,end:date});return <><Card className="detail-card"><div className="eyebrow">{date} · Main Tracker source</div><div className="facts">{[["Spend",amount(m.spend)],["Shopify net revenue",amount(m.revenue)],["Website ROAS",multiple(m.roas)],["Shopify orders",integer(m.orders)],["GA4 sessions",integer(m.sessions)],["GA4 purchases",integer(m.purchases)]].map(([l,v])=><div className="fact" key={l}>{l}<strong>{v}</strong></div>)}</div></Card><SectionCard title="Campaign spend and attributed outcomes"><DataTable heads={["Campaign","Spend","Platform revenue"]} rows={campaigns.map(c=>{const r=campaignMetrics(c.id,{start:date,end:date});return [<Button key={c.id} variant="link" className="p-0" onClick={()=>setDetail({type:"campaign",id:c.id})}>{c.name}</Button>,amount(r.spend),r.revenue===null?"Awareness":amount(r.revenue)]})}/></SectionCard><Card className="detail-card mt-4"><div className="eyebrow">Sample order ledger · {integer(m.orders)} records</div><DataTable heads={["Order ID","Customer","Net revenue"]} rows={within(orders,{start:date,end:date}).slice(0,10).map(o=>[<Button key={o.id} variant="link" className="p-0" onClick={()=>setDetail({type:"order",id:o.id})}>{o.id}</Button>,o.customerId,amount(o.net)])}/></Card></>}
    if(detail.type==="order"){const o=orders.find(v=>v.id===detail.id);if(!o)return null;return <Card className="detail-card"><div className="eyebrow">Shopify order ID · {o.id}</div><div className="facts">{[["Order date",o.date],["Customer ID",o.customerId],["Customer type",o.newCustomer?"First-time":"Returning"],["Product ID",o.productId],["Gross",amount(o.gross)],["Discount",amount(o.discount)],["Refund",amount(o.refund)],["Net merchandise revenue",amount(o.net)]].map(([l,v])=><div key={l} className="fact">{l}<strong>{v}</strong></div>)}</div><p className="source-note">Synthetic Shopify order ledger. No invented ad campaign attribution is assigned to this order.</p></Card>}
    if(detail.type==="product"){const product=products.find(v=>v.id===detail.id);if(!product)return null;const list=within(orders,p).filter(o=>o.productId===product.id);return <><Card className="detail-card"><div className="eyebrow">{product.id} · {product.category}</div><h3 className="font-semibold">{product.name}</h3><p className="muted-copy">{integer(list.length)} units · {amount(sum(list,"net"))} net merchandise revenue · {integer(product.stock)} stock snapshot</p></Card><SectionCard title="Sample linked orders"><DataTable heads={["Order","Date","Customer","Net"]} rows={list.slice(0,12).map(o=>[<Button key={o.id} variant="link" className="p-0" onClick={()=>setDetail({type:"order",id:o.id})}>{o.id}</Button>,o.date,o.customerId,amount(o.net)])}/></SectionCard></>}
    if(detail.type==="action"){const item=actionBy(detail.id||"");if(!item)return null;return <><Card className="detail-card"><div className="flex gap-2 flex-wrap"><Status value={item.priority}/><Status value={item.confidence}/><Status value={item.status}/></div><p className="muted-copy"><strong>Recommended action:</strong> {item.action}</p><div className="callout"><strong>Expected impact:</strong> {item.impact}<br/><span className="meta-copy">This is indicative. A measured outcome requires a completed test.</span></div><div className="facts"><div className="fact">Owner<strong>{item.owner}</strong></div><div className="fact">Review date<strong>{item.review}</strong></div></div><div className="source-note">Evidence: {item.evidence==="checkout"?"GA4 checkout and purchase events":item.evidence==="reconcile"?"GA4 vs Shopify comparison":`Campaign ${item.evidence}`}</div><Button variant="outline" onClick={()=>setDetail(item.evidence==="checkout"||item.evidence==="reconcile"?{type:"evidence",id:item.evidence}:{type:"campaign",id:item.evidence})}>Open supporting records</Button></Card><Card className="detail-card"><h3 className="font-semibold">Controlled test</h3><div className="space-y-2 text-sm leading-7"><p><strong>Hypothesis:</strong> {item.hypothesis}</p><p><strong>Control:</strong> {item.control}</p><p><strong>Duration:</strong> {item.duration}</p><p><strong>Success measure:</strong> {item.success}</p></div></Card><Card className="detail-card"><h3 className="font-semibold">Decision and measurement</h3><div className="field"><Label htmlFor="owner">Assigned owner</Label><Select value={item.owner} onValueChange={v=>update(item.id,{owner:v},"Owner assigned",v)}><SelectTrigger id="owner"><SelectValue/></SelectTrigger><SelectContent>{["Paid Media","E-commerce","Analytics","Marketing Lead"].map(v=><SelectItem key={v} value={v}>{v}</SelectItem>)}</SelectContent></Select></div><div className="flex gap-2 flex-wrap">{item.status==="Proposed"&&<Button onClick={()=>{update(item.id,{status:"Approved"},"Approved for test");toast.success("Action approved for a controlled test")}}>Approve test</Button>}{item.status==="Approved"&&<Button onClick={()=>{update(item.id,{status:"In test"},"Test started");toast.success("Test started")}}>Start test</Button>}{item.status==="In test"&&<div className="w-full"><p className="muted-copy">Enter observed control and test values for the agreed success measure. These are reviewer-entered examples and do not change Shopify actuals.</p><div className="grid grid-cols-2 gap-2 mt-2"><div className="field"><Label>Control value</Label><Input type="number" min="0" value={testControl} onChange={e=>setTestControl(e.target.value)} placeholder="e.g. 35"/></div><div className="field"><Label>Test value</Label><Input type="number" min="0" value={testVariant} onChange={e=>setTestVariant(e.target.value)} placeholder="e.g. 39"/></div></div><div className="field"><Label>Measurement note / unit</Label><Textarea value={testNote} onChange={e=>setTestNote(e.target.value)} placeholder="e.g. checkout completion %, 14-day matched period"/></div><Button onClick={()=>{const c=Number(testControl),t=Number(testVariant);if(testControl===""||testVariant===""||!Number.isFinite(c)||!Number.isFinite(t)||c<0||t<0||!testNote.trim()){toast.error("Enter both observed values and a measurement note");return}update(item.id,{status:"Measured",measurement:{control:c,test:t,period:stamp(),note:testNote.trim()}},"Test result recorded",`${c} control, ${t} test`);setTestControl("");setTestVariant("");setTestNote("");toast.success("Measured result recorded")}}>Record measured result</Button></div>}{item.measurement&&<div className="callout">Recorded sample: control {item.measurement.control}, test {item.measurement.test}. Difference: {(item.measurement.test-item.measurement.control).toFixed(2)} in the entered unit.<br/>{item.measurement.note}</div>}</div></Card>{item.history.length>0&&<Card className="detail-card"><h3 className="font-semibold">Action history</h3><div className="timeline">{item.history.map((h,i)=><p key={i}><strong>{h.event}</strong> · {h.at}<br/>{h.note}</p>)}</div></Card>}</>}
    if(detail.type==="agent")return <><EmptyNote>This demo agent answers a named set of questions using the connected sample records. Production answers require approved source access and definitions.</EmptyNote><div className="mt-5 space-y-2">{["What changed in ROAS?","Why did checkout change?","Which creative needs attention?","What is new-customer CAC?","What is urgent today?"].map(q=><Button key={q} variant="outline" className="w-full justify-start h-auto whitespace-normal text-left" onClick={()=>{setQuestion(q);setAgentAnswer(answer(q))}}>{q}</Button>)}</div><form className="flex gap-2 mt-5" onSubmit={e=>{e.preventDefault();setAgentAnswer(answer(question))}}><Input aria-label="Ask a question" placeholder="Ask about connected Commerce data" value={question} onChange={e=>setQuestion(e.target.value)}/><Button type="submit">Ask</Button></form>{agentAnswer&&<div className="agent-answer mt-5"><div className="eyebrow mb-2">Answer · {dateLabel(n)}</div>{agentAnswer}</div>}</>;
    return null;
  };
  function answer(q:string):React.ReactNode{const t=q.toLowerCase();if(/roas|spend|revenue/.test(t))return <><p>Website ROAS is {multiple(a.roas)} versus {multiple(b.roas)} previously. Shopify net revenue is {amount(a.revenue)} and paid media spend is {amount(a.spend)}. Revenue changed {((a.revenue/b.revenue-1)*100).toFixed(1)}%; spend changed {((a.spend/b.spend-1)*100).toFixed(1)}%.</p><p>Observed movement does not establish campaign causality. Review checkout and platform detail before reallocating budget.</p><Button variant="outline" onClick={()=>setDetail({type:"metric",id:"roas"})}>Open calculation and sources</Button></>;
    if(/checkout|funnel|conversion/.test(t))return <><p>GA4 checkout completion is {percent(a.completion)} versus {percent(b.completion)} in the previous equal period. The sample does not include payment failures or UX logs, so the root cause is unconfirmed.</p><Button variant="outline" onClick={()=>setDetail({type:"evidence",id:"checkout"})}>Open funnel evidence and test</Button></>;
    if(/creative|campaign|meta|google/.test(t))return <><p>Meta prospecting shows {percent(campaignMetrics("M-P",p).ctr)} CTR. The proposed action is an equal-budget creative test; its revenue impact cannot be estimated from CTR alone.</p><Button variant="outline" onClick={()=>setDetail({type:"campaign",id:"M-P"})}>Open campaign and creatives</Button></>;
    if(/customer|cac|crm|repeat/.test(t))return <><p>Blended new-customer CAC is {amount(a.cac)}: {amount(a.acquisitionSpend)} acquisition spend divided by {integer(a.newCustomers)} unique first-time Shopify purchasers. Dated Easy Rewards history is needed for a reliable repeat-purchase cohort measure.</p><Button variant="outline" onClick={()=>setDetail({type:"metric",id:"cac"})}>Open CAC calculation</Button></>;
    if(/urgent|priority|action|impact/.test(t))return <><p>Urgent: investigate checkout completion. The next action is to review payment and checkout failures, then test one verified fix. The impact range is a test hypothesis, not a promise.</p><Button variant="outline" onClick={()=>setDetail({type:"action",id:"A01"})}>Open action, owner and status</Button></>;
    return <><p>The connected Commerce sample cannot answer that question with evidence. It may need POS, store activity, CRM history or a definition that is not in this prototype.</p><Button variant="outline" onClick={()=>navigate("connections")}>View required sources</Button></>}
  return <SidebarProvider><Sidebar collapsible="offcanvas" variant="sidebar"><SidebarHeader className="p-5 border-b border-border"><div className="sidebar-brand flex items-center gap-2"><span className="size-8 bg-accent rounded-lg flex items-center justify-center text-primary"><BarChart3 className="size-5"/></span>Commerce OS</div></SidebarHeader><SidebarContent>{nav.map(g=><SidebarGroup key={g.title}><SidebarGroupLabel className="nav-label">{g.title}</SidebarGroupLabel><SidebarGroupContent><SidebarMenu>{g.items.map(item=><SidebarMenuItem key={item.id}><SidebarMenuButton isActive={view===item.id} onClick={()=>navigate(item.id)} tooltip={item.label}><item.icon className="size-4"/><span>{item.label}</span></SidebarMenuButton></SidebarMenuItem>)}</SidebarMenu></SidebarGroupContent></SidebarGroup>)}</SidebarContent><SidebarFooter className="p-4 border-t border-border"><div className="next-modules"><div className="eyebrow text-primary">BLACKBERRYS</div><p className="meta-copy mt-1">Commerce scope review · Module 1 of 3</p></div></SidebarFooter></Sidebar><SidebarInset className="app-main"><header className="topbar"><div className="flex items-center gap-3 min-w-0"><SidebarTrigger/><Separator orientation="vertical" className="h-5"/><div className="font-semibold truncate">{view==="overview"?"Performance Overview":titles[view]}</div></div><div className="flex gap-2 items-center no-print"><Status value="DEMO DATA"/><Button variant="outline" onClick={()=>setDetail({type:"agent"})}><Sparkles/> <span className="hidden sm:inline">Ask AI agent</span></Button><span className="size-8 rounded-full bg-[#17385a] text-white text-xs font-semibold grid place-items-center">BB</span></div></header><main className="page-content"><div className="page-header"><div><h1>{view==="overview"?"Performance Overview":titles[view]}</h1><p className="page-description">{view==="overview"?"Understand performance, inspect evidence and decide what to do next.":"Blackberrys · Commerce OS"}</p></div><Select value={String(n)} onValueChange={v=>{setN(Number(v));setReportReady(false)}}><SelectTrigger className="w-[220px] bg-white" aria-label="Reporting period"><CalendarDays className="size-4"/><SelectValue/></SelectTrigger><SelectContent><SelectItem value="7">22–28 Sep 2026 · 7 days</SelectItem><SelectItem value="14">15–28 Sep 2026 · 14 days</SelectItem></SelectContent></Select></div><div className="demo-strip"><span>Illustrative data for scope review · Source records through 28 Sep 2026</span><span>Action and checklist edits save only in this browser</span></div>{page()}<p className="scope-note">Commerce OS prototype · SOW V2 · Calculation definitions, baseline and reconciliation tolerances to be agreed in Week 1.</p></main></SidebarInset><Sheet open={!!detail} onOpenChange={open=>{if(!open){setDetail(null);setAgentAnswer(null)}}}><SheetContent side="right" className="w-full sm:max-w-[680px] gap-0 p-0"><SheetHeader className="p-6 border-b border-border"><div className="eyebrow">Commerce OS · Synthetic data</div><SheetTitle className="text-xl pr-8">{detailTitle()}</SheetTitle><SheetDescription>Evidence, calculations and next steps for {dateLabel(n)}</SheetDescription></SheetHeader><div className="sheet-body pt-5">{detailContent()}</div></SheetContent></Sheet><Toaster position="bottom-center" richColors/></SidebarProvider>;
}
